import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Types;

public class Probe {

	public static void main(String[] args) throws Exception {
		try (Connection c = DriverManager.getConnection("jdbc:h2:mem:probe2", "sa", "")) {
			try (Statement s = c.createStatement()) {
				s.execute("""
						create table t (
						  id bigint generated by default as identity primary key,
						  status varchar(8) not null,
						  created_at timestamp(6) with time zone not null,
						  constraint t_status_is_known check (status in ('PENDING','SETTLED','REJECTED','EXPIRED'))
						)
						""");
			}
			bind(c, "setString", ps -> ps.setString(1, "PENDING"));
			bind(c, "setObject/VARCHAR", ps -> ps.setObject(1, "PENDING", Types.VARCHAR));
			bind(c, "setObject/OTHER", ps -> ps.setObject(1, "PENDING", Types.OTHER));
			bind(c, "setObject(enum)", ps -> ps.setObject(1, Status.PENDING));
		}
	}

	enum Status { PENDING }

	interface Binder {
		void bind(PreparedStatement ps) throws Exception;
	}

	static void bind(Connection c, String label, Binder binder) {
		try (PreparedStatement ps = c.prepareStatement(
				"insert into t (status, created_at) values (?, current_timestamp)")) {
			binder.bind(ps);
			ps.executeUpdate();
			System.out.println(label + " -> ok");
		}
		catch (Exception e) {
			System.out.println(label + " -> " + e.getMessage().lines().findFirst().orElse(""));
		}
	}
}

