/**
 * Does a check constraint survive the connection that created it going away?
 * Flyway runs the migration on its own connection and closes it; Hibernate inserts later
 * on a pooled one.
 */
public class Probe2 {

	private static final String URL = "jdbc:h2:mem:probe3;DB_CLOSE_DELAY=-1";

	public static void main(String[] args) throws Exception {
		Connection keepAlive = DriverManager.getConnection(URL, "sa", "");

		try (Connection migrator = DriverManager.getConnection(URL, "sa", "");
				Statement s = migrator.createStatement()) {
			s.execute("""
					create table t (
					  id bigint generated by default as identity primary key,
					  status varchar(8) not null,
					  other varchar(8) not null,
					  constraint t_status_in check (status in ('PENDING','SETTLED')),
					  constraint t_status_or check (status = 'PENDING' or status = 'SETTLED'),
					  constraint t_columns_agree check (status = other)
					)
					""");
		}

		insert(URL, "after the creating connection closed");
	}

	static void insert(String url, String label) throws Exception {
		try (Connection c = DriverManager.getConnection(url, "sa", "");
				PreparedStatement ps = c.prepareStatement("insert into t (status, other) values (?, ?)")) {
			ps.setString(1, "PENDING");
			ps.setString(2, "PENDING");
			ps.executeUpdate();
			System.out.println(label + " -> ok");
		}
		catch (Exception e) {
			System.out.println(label + " -> " + e.getMessage().lines().findFirst().orElse(""));
		}
	}
}

