import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.Statement;

/**
 * Which check-constraint shapes survive the connection that created them going away, and
 * what is the actual failure underneath.
 */
public class Probe4 {

	public static void main(String[] args) throws Exception {
		run("string literal, IN", "check (status in ('PENDING','SETTLED'))");
		run("string literal, =", "check (status = 'PENDING')");
		run("string literal, cast", "check (cast(status as varchar(8)) in ('PENDING','SETTLED'))");
		run("column to column", "check (status = other)");
		run("numeric literal", "check (n between 0 and 10)");
		run("length, no literal", "check (char_length(status) > 3)");
		run("regexp literal", "check (status regexp '^[A-Z]+$')");
	}

	static void run(String label, String constraint) throws Exception {
		String url = "jdbc:h2:mem:p_" + Math.abs(label.hashCode()) + ";DB_CLOSE_DELAY=-1";
		Connection keepAlive = DriverManager.getConnection(url, "sa", "");

		try (Connection migrator = DriverManager.getConnection(url, "sa", "");
				Statement s = migrator.createStatement()) {
			s.execute("create table t (status varchar(8) not null, other varchar(8) not null, "
					+ "n bigint not null, constraint c " + constraint + ")");
		}

		try (Connection c = DriverManager.getConnection(url, "sa", "");
				PreparedStatement ps = c.prepareStatement("insert into t values (?, ?, ?)")) {
			ps.setString(1, "PENDING");
			ps.setString(2, "PENDING");
			ps.setLong(3, 5);
			ps.executeUpdate();
			System.out.println(pad(label) + "ok");
		}
		catch (Exception e) {
			Throwable root = e;
			while (root.getCause() != null) {
				root = root.getCause();
			}
			System.out.println(pad(label) + e.getMessage().lines().findFirst().orElse("")
					+ "  || root: " + root.getMessage().lines().findFirst().orElse(""));
			if (label.startsWith("string literal, IN")) {
				root.printStackTrace(System.out);
			}
		}
		keepAlive.close();
	}

	static String pad(String label) {
		return String.format("%-24s -> ", label);
	}
}

