				PreparedStatement ps = c.prepareStatement("insert into t values (?, ?, ?)")) {
			ps.setString(1, "PENDING");
			ps.setString(2, "PENDING");
			ps.setLong(3, 5);
			ps.executeUpdate();
			System.out.println(pad(label) + "ok");
		}
		catch (Exception e) {
			Throwable root = e;
			while (root.getCause() != null) {
				root = root.getCause();
			}
